PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE UI_Port (		  id integer primary KEY AUTOINCREMENT,		  type integer DEFAULT 0,		  extype boolean DEFAULT FALSE,		  source_type integer DEFAULT -1,		  exsource_type boolean DEFAULT FALSE,		  source_port varchar(16) DEFAULT '',		  dest_type integer DEFAULT -1,		  exdest_type boolean DEFAULT FALSE,		  dest_port varchar(16) DEFAULT '',		  field1 varchar(8) DEFAULT '',		  field2 integer DEFAULT 0,		  field3 integer DEFAULT 0,		  port_rule_id integer DEFAULT 0);
CREATE TABLE UI_PortRule (		  id integer primary KEY AUTOINCREMENT,		  name varchar(64) DEFAULT '',		  description varchar(128) DEFAULT '');
CREATE TABLE UI_networkObj (		 id integer primary KEY AUTOINCREMENT,		 name varchar(64) DEFAULT '');
CREATE TABLE UI_item (		 id integer primary KEY AUTOINCREMENT,		 type integer DEFAULT 0,		 field1 varchar(64) DEFAULT '',		 field2 varchar(64) DEFAULT '',		 field3 varchar(64) DEFAULT '',		 network_obj_id integer DEFAULT 0);
CREATE TABLE UI_scheduleRule (		 id integer primary KEY AUTOINCREMENT,		 name varchar(64) DEFAULT '',		 type integer DEFAULT 1);
CREATE TABLE UI_scheduleDate (		 id integer primary KEY AUTOINCREMENT,		 day varchar(32) DEFAULT '',		 schedule_rule_id integer DEFAULT 0);
CREATE TABLE UI_scheduleTime (		 id integer primary KEY AUTOINCREMENT,		 start varchar(8) DEFAULT '00:00',		 end varchar(8) DEFAULT '00:00',		 schedule_date_id integer DEFAULT 0);
CREATE TABLE UI_triggerRule (		 id integer primary KEY AUTOINCREMENT,		 enable integer DEFAULT 1,		 name varchar(64) DEFAULT '',		 schedule_rule_id integer DEFAULT 0);
CREATE TABLE UI_triggerRule_port (		 id integer primary KEY AUTOINCREMENT,		 type integer DEFAULT 0,		 trigger_rule_id integer DEFAULT 0,		 port_id integer DEFAULT 0);
CREATE TABLE UI_staticNAT (		 id integer primary KEY AUTOINCREMENT,		 enable integer DEFAULT 1,		 privateIP varchar(16) DEFAULT '',		 publicIP varchar(16) DEFAULT '',		 enable_portf integer DEFAULT 0);
CREATE TABLE UI_staticNAT_forwardRule (		 id integer primary KEY AUTOINCREMENT,		 static_nat_id integer DEFAULT 0,		 forward_rule_id integer DEFAULT 0,		 UNIQUE(static_nat_id , forward_rule_id) ON CONFLICT IGNORE );
CREATE TABLE UI_forwardRule (		 id integer primary KEY AUTOINCREMENT,		 uuid varchar(36) DEFAULT '',		 name varchar(64) DEFAULT '',		 enable integer DEFAULT 1,		 privateIP varchar(16) DEFAULT '',		 port_rule_id integer DEFAULT 0,		 forward_port integer DEFAULT 0,		 schedule_rule_id integer DEFAULT 0);
CREATE TABLE UI_accessControl (		 id integer primary KEY AUTOINCREMENT,		 enable integer DEFAULT 1,		 schedule_rule_id integer DEFAULT 0);
CREATE TABLE UI_accessControl_networkObj (		 id integer primary KEY AUTOINCREMENT,		 access_control_id integer DEFAULT 0,		 network_obj_id integer DEFAULT 0,		 UNIQUE(access_control_id , network_obj_id) ON CONFLICT IGNORE );
CREATE TABLE UI_accessControl_portRule (		 id integer primary KEY AUTOINCREMENT,		 access_control_id integer DEFAULT 0,		 port_rule_id integer DEFAULT 0,		 UNIQUE(access_control_id , port_rule_id) ON CONFLICT IGNORE );
CREATE TABLE UI_pinholeRule (		 id integer primary KEY AUTOINCREMENT,		 uuid varchar(36) DEFAULT '',		 name varchar(64) DEFAULT '',		 enable integer DEFAULT 1,		 publicIP varchar(50) DEFAULT '',		 publicDomain varchar(256) DEFAULT '',		 privateIP varchar(50) DEFAULT '',		 port_rule_id integer DEFAULT 0,		 schedule_rule_id integer DEFAULT 0);
CREATE TABLE UI_parentalRule (		 uuid varchar(36) primary KEY,		 name varchar(256) DEFAULT '',		 description varchar(256) DEFAULT '',		 enable integer DEFAULT 1,		 type integer DEFAULT 0,		 scheduleType integer DEFAULT 0,		 scheudleDay varchar(30) DEFAULT '',		 scheduleStart varchar(5) DEFAULT '',		 scheduleEnd varchar(5) DEFAULT '',		 created_at INTEGER DEFAULT (strftime('%s', 'now')));
CREATE TABLE UI_parentalMAC (		 uuid varchar(36) DEFAULT '',		 mac varchar(256) DEFAULT '',		 UNIQUE(uuid , mac) ON CONFLICT IGNORE );
CREATE TABLE UI_parentalText (		 uuid varchar(36) DEFAULT '',		 type integer DEFAULT 0,		 text varchar(256) DEFAULT '',		 UNIQUE(uuid , text) ON CONFLICT IGNORE );
CREATE TABLE UI_blockDevice (		 mac varchar(256) primary KEY,		 block integer DEFAULT 0);
CREATE TABLE UI_routes6 (		 id integer primary KEY AUTOINCREMENT,		 prefix6 varchar(64) DEFAULT  '',		 gw6 varchar(256) DEFAULT '',		 metric6 integer DEFAULT 0,		 state integer DEFAULT 0);
CREATE TABLE UI_analysis (		 id integer primary KEY AUTOINCREMENT,		 timestamp varchar(12) DEFAULT (strftime('%s', 'now')),		 page_name varchar(128) DEFAULT '');
CREATE TABLE UI_qsw (		 id integer primary KEY AUTOINCREMENT,		 timestamp varchar(36) DEFAULT (strftime('%d/%m/%Y @ %H:%M:%S', 'now')),		 device_name varchar(128) DEFAULT '');
CREATE TABLE UI_FsamIconUpdate (		 icon_id integer primary KEY AUTOINCREMENT,		 dev_cat varchar(64) DEFAULT '',		 icon_name varchar(64) DEFAULT '',		 icon_url_path varchar(128) DEFAULT '');
DELETE FROM sqlite_sequence;
COMMIT;
